<script setup lang="ts">import {fixed,probability,logValue} from '../utils/format';const props=defineProps<{node:any,target:string,labels?:Record<string,string>}>();const label=(id:string)=>props.labels?.[id]||id;</script><template><div class="plan-node"><header><span class="depth-badge">第{{node.depth}}层 · 累计成本 {{node.cumulative_cost}} · 剩余预算 {{node.remaining_budget}}</span><strong>{{target}}=1 后验 {{probability(node.posterior[1].probability,node.posterior[1].probability_underflow)}}</strong></header><p class="node-metrics">H={{fixed(node.entropy,6)}} bit → 期望剩余 {{fixed(node.expected_remaining_entropy,6)}} bit · 联合logZ {{logValue(node.log_evidence)}}<span v-if="node.evidence_probability_underflow"> · 证据概率exp下溢（仍可行）</span></p><p class="node-evidence">证据 {{JSON.stringify(node.evidence)}}</p><p v-if="node.decision.type==='stop'" class="stop-badge">停止：{{node.decision.reason}}</p><template v-else><p class="observe-badge">观测 <b>{{label(node.decision.node_id)}}</b>（成本 {{node.decision.cost}}）→ 分支后期望熵 {{fixed(node.decision.expected_entropy,6)}} bit</p><div class="plan-branches"><div v-for="b in node.branches" :key="b.state" :class="['plan-branch',{skipped:b.skipped_zero_probability}]"><p v-if="b.skipped_zero_probability" class="branch-line">{{label(node.decision.node_id)}}={{b.state}} · 严格零概率分支跳过</p><template v-else><p class="branch-line">{{label(node.decision.node_id)}}={{b.state}} · 分支概率 {{probability(b.probability,b.probability_underflow)}} · log {{logValue(b.log_probability)}}</p><PlanNode :node="b.child" :target="target" :labels="labels"/></template></div></div></template></div></template>
